"use strict";const r=require("../utils/request.js");exports.batchConfirmRecurringPendingItems=function(e){return r.http.post("/recurring/pending-items/batch-confirm",{ids:e})},exports.batchSkipRecurringPendingItems=function(e){return r.http.post("/recurring/pending-items/batch-skip",{ids:e})},exports.confirmRecurringPendingItem=function(e,t){return r.http.post(`/recurring/pending-items/${e}/confirm`,t||{})},exports.createRecurringRule=function(e){return r.http.post("/recurring/rules",e)},exports.deleteRecurringRule=function(e){return r.http.del(`/recurring/rules/${e}`)},exports.fetchRecurringPendingItems=function(){return r.http.get("/recurring/pending-items")},exports.fetchRecurringRule=function(e){return r.http.get(`/recurring/rules/${e}`)},exports.fetchRecurringRules=function(){return r.http.get("/recurring/rules")},exports.pauseRecurringRule=function(e){return r.http.post(`/recurring/rules/${e}/pause`)},exports.resumeRecurringRule=function(e){return r.http.post(`/recurring/rules/${e}/resume`)},exports.skipRecurringPendingItem=function(e){return r.http.post(`/recurring/pending-items/${e}/skip`)},exports.updateRecurringRule=function(e,t){return r.http.put(`/recurring/rules/${e}`,t)};
